import {notation,formulaLesson,workflowLesson,indicatorsLesson,readingSteps} from './cfd-lessons.js';
import {loadNumericalChecks,numericalReviewPanel} from './cfd-numerical.js';
const terms = {
 zh: {open:'CFD 怎么算',hint:'从区域、公式到参数与误差，逐项查看',close:'关闭说明',title:'读懂这次风热计算',tabs:['计算流程','公式与单位','参数为什么这样选','区域关系','结果与误差'],
  intro:'CFD（计算流体力学）把城市周围的空气分成许多小单元，用质量、动量和热量守恒求出平均风速与温度。本项目比较同一天气下的现状屋顶和冷屋顶。',
  workflow:[['几何','PLATEAU LOD1 建筑投影按来源高度拉伸。建筑实体占据的空间从空气网格中扣除。设计区沿用 2020 年町丁目工作边界。'],['网格','核心街道细、外围空气粗。当前为阶梯状建筑边界；窄缝可能闭合，树冠和架空铁路尚未完整解析。'],['边界','南侧规定来流风与气温，北侧允许出流。地面及建筑表面速度为零，侧面和顶部采用对称条件。'],['求解','OpenFOAM 2412，稳态 RANS k–ε 与 Boussinesq 浮力。RANS 计算时间平均流动，k–ε 近似未解析的湍流。SIMPLE 反复修正速度与压力。'],['检查','先检查网格，再检查残差、街道指标和热收支；另外改变建筑范围、外边界与网格，观察结果是否稳定。'],['比较','两方案使用同一网格、天气、采样点和色标。1.5 m 高度的 T − Tin 是该加热模型的温度偏离，当前场尚未收敛。稳态迭代次数不是经过的物理秒数。']],
  formulaNames:['周边建筑筛选','空气盒子的尺寸','迎风阻塞率代理','来流随高度变化','空气与热量守恒','湍流与浮力','规定屋顶热输入','前后比较与热收支'],
  paramColumns:['参数','发布场记录值','选择依据与用途'],
  paramNotes:['观测：JMA 东京站 2025-08-30 13:00 JST；观测站风并非街道实测风。','观测：风速计高度按 JMA 站点表。','观测：同一小时的气温与水平面总太阳辐射。','设计假设：按反照率把规定屋顶显热从 138.67 降至 69.33 W/m²，其余条件相同；求解器关闭辐射。','设计假设：fH 未经实测校准，计划比较 0.10 / 0.20 / 0.30。','模型假设：中性来流与粗糙地面一致；真实上游城市粗糙度仍需核查。','模型常数：空气物性与湍流热扩散参数，记录于计算配置。','方法：稳态平均流动及湍流闭合，适合先做条件性前后比较。','几何：来源体量与平地近似；发布年 2025 不等于逐栋调查年。','数值：阶梯网格，核心近地约 0.5 m、核心表面约 1 m；需细化比较。','数值：温度线性求解容差与外层残差目标；不是温度预测精度。','显示：共同 1.5 m 采样面与 5 m 输出栅格；输出格距不等于求解网格尺寸。'],
  regionTitle:'评价区 ⊂ 建模建筑包络 ⊂ 计算外框',
  regions:[['设计评价区','只在这里汇总设计效益，277 个核心对象参与屋顶方案。课程正式边界仍待确认。'],['显式建筑范围','近邻街区和筛选出的较远高层决定遮挡、绕流和尾流。蓝框只是所选建筑的包络，框内也可能有未选建筑。'],['外部空气缓冲区','外框界定空气方程的求解空间。保留空白缓冲有助于隔开数值边界；它没有把现实城市变成空地，也不能代替真实上游来流。']],
  auditTitle:'范围审计与尺寸复算', current:'当前发布输入', revised:'补齐后的 6H 候选', expanded:'10H 扩展候选',notRun:'候选几何已备，新的流场敏感性结果待完成',
  checks:[['收敛','残差下降，并且目标街道指标随迭代稳定。程序结束与稳定收敛需要分别核实。'],['几何敏感性','在同一个大空气盒中比较补齐的 6H 与 750 m + 10H 建筑，保持核心网格、天气与热源一致。'],['边界敏感性','固定建筑几何，仅改变侧边界、顶部或出口距离；不能同时加建筑再把差异归因于边界。'],['网格敏感性','用同一几何和条件比较至少两档网格，关注街巷连通性和实际加热屋顶面积。'],['来流与热收支','空场检查 U、k、ε 的剖面漂移；单独核对输入屋顶热量与边界净输出。'],['现场或基准验证','与相应风洞、现场或可信非等温基准比较，才能评价模型对现实的预测误差。']],
  limits:'当前发布的是第 100 次迭代中间场。几何规则和网格质量记录已有证据，收敛、热收支及范围敏感性尚未完成。T − Tin 是规定屋顶加热模型的未收敛温度偏离；树木、完整辐射、地表蓄热和真实建筑能耗尚未全部耦合。',
  criteria:'本项目预设比较标准：核心区风矢量 RMS 差 ≤ 0.05Uref（0.125 m/s）；可报告的改造效应在改范围后保持符号，变化 ≤ 10%。接近零的效应按 0.01 m/s 或 0.01 K 的暂定报告分辨率判断，不能用相对百分比放大。以上是项目判据，不是 COST 或 AIJ 的统一阈值。',
  calcTitle:'亲自代入屋顶热输入',calcNote:'这里只重算公式值；主视图的风热场来自离线 CFD。',albedo:'改造反照率 α',fraction:'显热转换 fH',baseline:'现状 qH',retrofit:'改造 qH',sources:'依据与计算记录',raw:'读取范围审计 JSON →',size:'空气盒 / km',objects:'建筑对象',added:'新增',verified:'几何核查',pending:'风场比较待完成' },
 en: {open:'How CFD works',hint:'Explore the areas, equations, parameters and checks',close:'Close guide',title:'Read this wind and heat calculation',tabs:['Workflow','Equations and units','Parameter choices','Area relationships','Results and error'],
  intro:'CFD divides the air around the city into cells. It solves conservation of mass, momentum and heat. This project compares existing and cool roofs under the same weather.',
  workflow:[['Geometry','PLATEAU LOD1 projections are extruded to source heights. Solid buildings are removed from the air mesh. The working design boundary follows the 2020 census towns.'],['Mesh','Fine cells cover core streets; coarse cells cover outer air. Buildings use staircase boundaries. Narrow gaps can close; trees and elevated rail are not fully resolved.'],['Boundaries','Wind and temperature enter from the south. Air can leave to the north. Ground and building walls have zero velocity; sides and top use symmetry.'],['Solve','OpenFOAM 2412 uses steady RANS k–ε and Boussinesq buoyancy. RANS solves mean flow; k–ε represents unresolved turbulence. SIMPLE repeatedly corrects velocity and pressure.'],['Check','Inspect mesh, residuals, street metrics and heat balance. Change geometry extent, outer boundaries and mesh to test whether results remain stable.'],['Compare','Both roof cases share mesh, weather, samples and colour scales. T − Tin at 1.5 m is the temperature departure in this heated model; the published field has not converged. Steady iterations are not physical seconds.']],
  formulaNames:['Select surrounding buildings','Size the air box','Projected blockage proxy','Inlet wind with height','Conservation of air and heat','Turbulence and buoyancy','Prescribed roof heat','Paired change and heat balance'],
  paramColumns:['Parameter','Published-field value','Reason and role'],
  paramNotes:['Observed: JMA Tokyo, 2025-08-30 13:00 JST. Station wind is not measured street wind.','Observed: anemometer height from the official JMA station table.','Observed: air temperature and horizontal irradiance at the same hour.','Design assumption: albedo sets prescribed roof heat to 138.67 / 69.33 W/m². Other conditions match; solver radiation is off.','Assumed: fH awaits calibration; planned levels are 0.10 / 0.20 / 0.30.','Model assumption: matching inlet and ground roughness. Actual upstream urban roughness still needs review.','Model constants: air properties and turbulent heat diffusion, recorded in case files.','Method: steady mean flow and turbulence closure for a conditional comparison.','Geometry: source massing and flat ground. Release year 2025 differs from building survey year.','Numerical: staircase mesh; about 0.5 m near core ground and 1 m at core surfaces. Refinement comparison remains needed.','Numerical: temperature linear tolerance and outer residual target. These are not prediction accuracy.','Display: common 1.5 m samples on a 5 m output grid. Output spacing differs from solver cell size.'],
  regionTitle:'Design area ⊂ building envelope ⊂ outer air box',regions:[['Design area','Report design effects here. The roof intervention covers 277 core objects. The boundary was unconfirmed at the historical trial stage. The current study boundary is defined in Mapping.'],['Explicit buildings','Nearby blocks and selected distant tall buildings affect shielding, deflection and wakes. The blue envelope can also contain omitted buildings.'],['Outer air buffer','The outer box bounds the air equations. Empty numerical padding separates boundaries from buildings; it cannot replace actual urban approach flow.']],
  auditTitle:'Geometry audit and recalculated sizes',current:'Published input',revised:'Completed 6H candidate',expanded:'Expanded 10H candidate',notRun:'Candidate geometry prepared; new flow sensitivity results pending',
  checks:[['Convergence','Residuals decrease and target street metrics stabilize. Solver exit and stable convergence require separate evidence.'],['Geometry sensitivity','Compare completed 6H and continuous 750 m + 10H buildings in one large box. Keep the core mesh, weather and roof heating fixed.'],['Boundary sensitivity','Keep buildings fixed and change side, top or outlet distances. Adding buildings at the same time would confound the comparison.'],['Mesh sensitivity','Compare at least two resolutions with the same geometry and conditions. Inspect street connectivity and realized heated-roof area.'],['Inlet and heat balance','Use an empty box to check U, k and ε profile drift. Independently compare roof power and net boundary heat output.'],['Validation','Compare with relevant tunnel, field or trusted non-isothermal benchmarks to assess error relative to reality.']],
  limits:'The published field is an intermediate snapshot at iteration100. Geometry rules and mesh records are available. Convergence, heat balance and extent sensitivity remain pending. T − Tin is the unconverged temperature departure in the prescribed-roof-heating model; full radiation, storage, trees and actual building energy are not all coupled.',
  criteria:'Project comparison criteria: core wind-vector RMS change ≤ 0.05Uref (0.125 m/s). A reportable intervention effect retains its sign and changes by ≤10%. Near-zero effects use provisional reporting resolutions of 0.01 m/s or 0.01 K. These are project criteria, not universal COST or AIJ thresholds.',
  calcTitle:'Try the roof-heat equation',calcNote:'This calculator updates formula values. Main wind and heat fields come from offline CFD.',albedo:'Retrofit albedo α',fraction:'Sensible fraction fH',baseline:'Existing qH',retrofit:'Retrofit qH',sources:'Sources and calculation records',raw:'Read the geometry audit JSON →',size:'Air box / km',objects:'Building objects',added:'Added',verified:'Geometry audit',pending:'Flow comparison pending' },
 ja: {open:'CFD の計算方法',hint:'範囲・式・パラメータ・誤差を順に確認',close:'説明を閉じる',title:'風・熱計算を読み解く',tabs:['計算の流れ','式と単位','パラメータの選択','範囲の関係','結果と誤差'],
  intro:'CFD は都市周辺の空気を小さなセルに分け、質量・運動量・熱の保存則を解きます。同じ気象条件で現状屋根と高反射率屋根を比較します。',
  workflow:[['形状','PLATEAU LOD1 の投影を出典の高さで立ち上げます。建物の固体部分を空気メッシュから除きます。設計作業範囲は2020年町丁目境界です。'],['メッシュ','対象街路を細かく、外側の空気を粗く分割します。建物は階段状境界で、狭い隙間が閉じる場合があります。樹冠や高架鉄道は十分に解析されていません。'],['境界条件','南から風と気温を与え、北で流出を許します。地表と建物表面は速度ゼロ、側面と上面は対称条件です。'],['求解','OpenFOAM 2412、定常 RANS k–ε と Boussinesq 浮力を使用します。RANS は平均流れ、k–ε は未解像の乱流を表します。SIMPLE で速度と圧力を反復修正します。'],['確認','メッシュ、残差、街路指標、熱収支を確認します。建物範囲、外部境界、解像度を変え、結果の安定性を調べます。'],['比較','両案で同じメッシュ、気象、サンプル、色尺度を使います。1.5 m の T − Tin は加熱モデル内の温度偏差で、公開場は未収束です。定常反復回数は物理的な秒数ではありません。']],
  formulaNames:['周辺建物の選択','空気領域の寸法','投影閉塞率の代理値','高さ別の流入風','空気と熱の保存','乱流と浮力','指定した屋根熱','前後差と熱収支'],
  paramColumns:['パラメータ','公開場の記録値','選択理由・役割'],paramNotes:['観測：気象庁東京、2025-08-30 13:00 JST。観測点風速と街路実測風は異なります。','観測：気象庁の観測点表による風速計高さ。','観測：同じ時刻の気温と全天水平面日射。','設計仮定：対象屋根の反射率だけを変更。','仮定：fH は未校正で、0.10 / 0.20 / 0.30 を比較予定。','モデル仮定：流入と地面の粗度を一致。実際の上流市街地粗度は要確認。','モデル定数：空気物性と乱流熱拡散を設定ファイルに記録。','方法：定常平均流れと乱流モデルによる条件付き比較。','形状：出典の建物形状と平地近似。公開年と個別調査年は異なります。','数値：階段状メッシュ。対象地表付近は約0.5 m、対象建物表面は約1 m。細分化比較が必要です。','数値：温度の線形解法許容値と外部反復残差目標。予測精度とは異なります。','表示：同じ高さ1.5 m、出力格子5 m。出力間隔は求解セル寸法とは異なります。'],
  regionTitle:'設計対象 ⊂ 建物包絡 ⊂ 外部空気領域',regions:[['設計対象','設計効果を集計する範囲です。277件の対象建物を屋根改修の対象とします。授業の正式境界は要確認です。'],['明示的な建物','近隣街区と選択した遠方の高層建物が遮蔽・迂回・後流を決めます。青い包絡内にも未採用建物があり得ます。'],['外側の空気バッファ','空気の方程式を解く外枠です。空白の数値バッファで境界を建物から離しますが、実際の都市の流入条件を代替できません。']],
  auditTitle:'範囲の監査と寸法再計算',current:'公開中の入力',revised:'補完した6H候補',expanded:'10H拡張候補',notRun:'候補形状を準備済み、流れの感度は未計算',
  checks:[['収束','残差と対象街路指標の安定を確認します。ソルバー終了と収束は別に確認します。'],['形状感度','同じ大きな空気領域で補完6Hと750m＋10Hを比較し、対象メッシュ・気象・屋根加熱を固定します。'],['領域感度','建物を固定し、側面・上面・出口距離だけを変更します。同時に建物を追加すると影響を区別できません。'],['メッシュ感度','同一条件で少なくとも二つの解像度を比較し、街路の連結性と実際の加熱面積を調べます。'],['流入・熱収支','空領域で U・k・ε 分布の変化を確認し、屋根入力と境界正味出力を別に比較します。'],['妥当性確認','対応する風洞・現地・信頼できる非等温基準と比較し、現実に対する予測誤差を評価します。']],
  limits:'公開場は反復100回時点の中間場です。形状選択とメッシュの記録はありますが、収束・熱収支・範囲感度は未完了です。T − Tin は指定屋根加熱モデルの未収束温度偏差で、日射・蓄熱・樹木・実際の建物エネルギーはすべて連成されていません。',
  criteria:'暫定比較基準：対象風ベクトルの RMS 差 ≤ 0.05Uref（0.125 m/s）。報告可能な改修効果は符号を保ち、範囲変更による差が10%以下。ゼロ付近は0.01 m/sまたは0.01 Kの報告分解能で判断します。COST・AIJの一律基準ではありません。',
  calcTitle:'屋根熱の式を試す',calcNote:'ここでは式の値だけを再計算します。主画面の風・熱場は別途実行したCFDです。',albedo:'改修反射率 α',fraction:'顕熱変換率 fH',baseline:'現状 qH',retrofit:'改修 qH',sources:'出典・計算記録',raw:'範囲監査 JSON →',size:'空気領域 / km',objects:'建物オブジェクト',added:'追加',verified:'形状確認',pending:'流れの比較は未完了' }
};


Object.assign(terms.zh,{basis:'建筑筛选：dn ≤ max(500 m, 6Hn)，Hn 取各栋建筑自身高度。原 500 m 是固定项目值；10 × 48.5 = 485 m 仅作尺度核对，不能反推原设置的来源。外框按最高保留建筑 235.2 m 计算，上游至少 1,176 m、下游 3,528 m、最高屋顶上方 1,176 m。5/15/5H 是本项目保守起点。COST 732 §5.4–5.6 提供几何和边界建议，并要求敏感性检查；主要适用于中性风场，不能据此认定本轮热模型已验证。',comparison:'下阶段先在同一个 8.640 × 7.552 × 1.472 km 空气盒中比较 6H 与连续 750 m + 10H；随后固定 6H 建筑，仅把横向宽度缩至 6.272 km。边界按同一 64 m 基网格取整，目标是保留核心格点；实际单元与采样要在生成网格后核对。表内为规则计算的起始外框，试验外框按 64 m 对齐；新参考组进度见下方记录，范围对比结果待完成。'});
Object.assign(terms.en,{basis:'Building selection uses dn ≤ max(500 m,6Hn), with each building’s own height. The old 500 m floor is a fixed project choice. Comparing it with 10 × 48.5 = 485 m is a scale check, not its original derivation. At Hmax = 235.2 m, project clearances start at 1,176 m upstream, 3,528 m downstream and 1,176 m above roofs. COST 732 supports geometry and boundary guidance with sensitivity checks; its mainly neutral-flow scope does not validate this heat model.',comparison:'Compare 6H and continuous 750 m + 10H in one 8.640 × 7.552 × 1.472 km air box. Then keep 6H buildings fixed and reduce only the lateral width to 6.272 km. Bounds align to the same 64 m lattice to target common core cells. Actual cells and samples must be checked after meshing. Table sizes are rule-based starting extents; experiment boxes align to 64 m. The reference workflow is recorded below; extent comparison results are pending.'});
Object.assign(terms.ja,{basis:'建物選択は dn ≤ max(500 m,6Hn) で、Hn は各建物自身の高さです。旧500 mは固定プロジェクト値です。10×48.5=485 mは尺度の確認で、旧設定の根拠を逆算したものではありません。最高235.2 mに対し上流1,176 m、下流3,528 m、最高屋根上1,176 mを初期余白とします。COST732の形状・境界助言には感度確認が必要で、中立風場を主対象とし、本熱モデルの妥当性確認にはなりません。',comparison:'同じ8.640×7.552×1.472km領域で6Hと750m連続街区＋10Hを比較後、6H建物を固定し横幅だけ6.272kmに縮めます。同一64 m基礎格子に境界を合わせ、対象格子を揃える設定です。実際のセルとサンプルは生成後に照合します。表は形状規則の初期寸法で、試験領域は64 mに整列します。新参照の進捗は下に記録し、範囲比較結果は未完了です。'});
Object.assign(terms.zh,{farHighrise:'纯 10H 高层候选',expanded:'750 m + 10H 连续街区候选'});
Object.assign(terms.en,{farHighrise:'Tall-building 10H candidate',expanded:'Continuous 750 m + 10H candidate'});
