terms.zh.workflow.push(['碳与体感','CO₂ 清单、空气温升和体感热风险分别核算。CO₂ 浓度需要排放质量源及输运方程，UTCI 等体感指标还需要辐射与湿度等条件；当前均未完整耦合。']);
terms.en.workflow.push(['Carbon and comfort','CO₂ inventories, air temperature and thermal comfort are separate outputs. Concentration needs mass sources and transport; comfort indices need radiation and humidity. These are not fully coupled here.']);
terms.ja.workflow.push(['炭素と体感','CO₂排出量、気温、体感熱リスクは別の指標です。濃度には質量源・輸送、体感指標には日射・湿度などが必要で、現状ではすべて連成されていません。']);
terms.ja.paramNotes[3]='設計仮定：反射率から指定屋根顕熱を138.67／69.33 W/m²とし、他条件を揃えます。求解器の日射計算は無効です。';
terms.zh.comparison+=' 这次同时改变连续覆盖和逐栋高度范围，差异首先归为联合范围敏感性；必要时用纯 10H 拆分原因。';
terms.en.comparison+=' Coverage distance and the height rule change together; this is a joint extent test. Pure 10H can later separate their roles.';
terms.ja.comparison+=' 連続距離と高さ規則を同時に変える共同範囲感度で、必要なら純10Hで要因を分けます。';
terms.zh.criteria='两组先通过收敛与热收支检查，再评估范围敏感性差异。同一屋顶方案、共同 1.5 m 有效点的风矢量 RMS 差除以 Uref，项目目标 DU ≤ 0.05；本轮对应分子的 RMS 差 ≤ 0.125 m/s。M 取核心开放地面的平均风速或平均温差；两屋顶方案的均值差 ΔM 在改范围后保持符号，相对变化 ≤ 10%。接近零的 ΔM 按 0.01 m/s 或 0.01 K 暂定报告分辨率判断，不当作预测精度。以上为项目判据。';
terms.en.criteria='Assess extent sensitivity differences after both settings pass convergence and heat balance. Compare the same roof case at common valid 1.5 m points: DU ≤ 0.05; its RMS numerator is ≤ 0.125 m/s at the current Uref. M is mean wind speed or mean temperature departure over core open ground. The paired roof effect ΔM should retain its sign and change by ≤ 10%. Near-zero ΔM uses provisional reporting steps of 0.01 m/s or 0.01 K, not prediction accuracy. These are project criteria.';
terms.ja.criteria='両設定の収束・熱収支確認後に範囲感度差を評価します。同じ屋根案、共通1.5m有効点のDU≤0.05、現在のUrefではRMS分子≤0.125m/sをプロジェクト目標とします。Mは対象屋外の平均風速または平均温度差で、屋根案の差ΔMは符号を保ち変化≤10%を目標とします。ゼロ付近は0.01m/s・0.01Kの暫定表示刻みで判断し、予測精度とはしません。';
Object.assign(terms.zh,{size:'规则起始外框 / km',alignedTitle:'本轮试验外框（64 m 对齐）',runSnapshot:'新计算检查时间',trialNames:['补齐 6H · 参考','750 m + 10H · 联合范围','补齐 6H · 侧边界'],proxy:'阻塞率代理'});
Object.assign(terms.en,{size:'Rule-based starting box / km',alignedTitle:'Experiment boxes aligned to 64 m',runSnapshot:'New-job check time',trialNames:['Completed 6H · reference','750 m + 10H · joint extent','Completed 6H · side boundary'],proxy:'Blockage proxy'});
Object.assign(terms.ja,{size:'規則による初期領域 / km',alignedTitle:'今回の試験領域（64 m整列）',runSnapshot:'新計算の確認時刻',trialNames:['補完6H・参照','750 m＋10H・共同範囲','補完6H・側面境界'],proxy:'閉塞率の代理'});
terms.zh.tabs=['从零读流程','公式与每个字母','参数为什么这样选','区域关系','读图与指标','检查与误差'];
terms.en.tabs=['Start here','Equations and symbols','Parameter choices','Areas','Read the results','Checks and error'];
terms.ja.tabs=['最初から読む','式と全記号','パラメータ','範囲の関係','図と指標','確認と誤差'];
Object.assign(terms.zh,{metricHelp:'这些数值怎么看 ↗',allFormulas:'展开所有公式与符号',collapseFormulas:'收起公式',formulaIntro:'按计算顺序逐项展开。每个公式都有一句话解释、全部符号与单位、数值例子，以及高低值的含义。'});
Object.assign(terms.en,{metricHelp:'How to read these values ↗',allFormulas:'Open all equations and symbols',collapseFormulas:'Collapse equations',formulaIntro:'Open each equation in order. Each has a plain explanation, every symbol and unit, an example, and a guide to higher and lower values.'});
Object.assign(terms.ja,{metricHelp:'数値の読み方 ↗',allFormulas:'全ての式と記号を開く',collapseFormulas:'式を閉じる',formulaIntro:'順番に式を開くと、一文の説明、全記号と単位、数値例、大きい・小さい値の意味を読めます。'});
terms.zh.workflow=[['平均流动与湍流','风会不规则波动，称为湍流。稳态 RANS（雷诺平均流动方程）求平均风，用 k–ε 模型估算波动对平均混合的作用；SIMPLE 算法让压力和速度反复协调。'],['无滑移','空气紧贴固定建筑和地面时，速度相对固体为零。这是壁面的条件；街道中的空气仍会流动。'],['绝热与携热','本轮地面、墙面、周边建筑与空气无热交换，核心屋顶规定显热。空气仍能在街道流动，并从进出口携带热量。'],['网格与采样','网格是求解用的三维空气单元；采样是在结果中取读数。本页在1.5 m高度取值，输出格距5 m，不能把它当成求解单元大小。'],['收敛、敏感性与验证','收敛看计算是否稳定；敏感性看换范围或网格是否改变结果；验证看计算与风洞或实测是否吻合。三种检查回答不同的问题。'],['COST 732 是什么','2007年欧洲城市风场计算最佳实践指南。本项目使用其中的几何与边界建议，再做敏感性检查；它没有直接验证本轮屋顶热模型。'],['碳与体感','CO₂清单需建筑能耗与排放系数；浓度需质量源与输运方程；体感热需辐射和湿度等。它们与本页空气温差分别核算。']];
terms.en.workflow=[['Mean flow and turbulence','Wind fluctuates irregularly: turbulence. Steady RANS solves mean flow; k–ε models how fluctuations mix it. SIMPLE iteratively coordinates pressure and velocity.'],['No slip','Air touching a fixed wall or ground has zero velocity relative to that surface. Air in the street still moves.'],['Adiabatic walls and heat transport','Ground, walls and context buildings exchange no heat with air in this model; core roofs supply prescribed heat. Moving air still carries heat through streets, inlet and outlet.'],['Mesh and samples','The mesh consists of 3D air cells used by the solver. Samples are readings from its result: here 1.5 m high on a 5 m output grid. Output spacing is not solver cell size.'],['Convergence, sensitivity and validation','Convergence checks stability, sensitivity checks changes in extent or mesh, and validation compares with tunnel or field data. Each answers a different question.'],['What COST 732 means','A 2007 European urban-wind best-practice guide. This project uses its geometry/boundary advice with sensitivity checks. It does not validate this roof-heat model.'],['Carbon and comfort','CO₂ inventories need energy and emission factors; concentration needs mass sources and transport; comfort needs radiation and humidity. Each is separate from this air-temperature calculation.']];
terms.ja.workflow=[['平均流れと乱流','風の不規則な変動を乱流と呼びます。定常RANSは平均流れ、k–εは変動の混合作用を求め、SIMPLEで圧力と速度を反復調整します。'],['滑りなし','固定建物や地面に接する空気の速度は固体に対してゼロです。街路内の空気は流れます。'],['断熱と空気の熱輸送','本設定では地面・壁・周辺建物と空気は熱交換せず、対象屋根に指定熱を与えます。空気は街路・流入・流出を通して熱を運びます。'],['メッシュとサンプル','メッシュは求解用3D空気セル、サンプルは結果の読取りです。高さ1.5 m・出力格子5 mは求解セル寸法とは別です。'],['収束・感度・検証','収束は計算安定性、感度は範囲・格子変更の影響、検証は風洞・実測との一致を調べます。別の問いに答える確認です。'],['COST 732とは','2007年の欧州都市風計算ベストプラクティス文書です。形状・境界助言と感度確認を使いますが、今回の屋根熱モデルの検証にはなりません。'],['炭素と体感','CO₂排出量にはエネルギーと係数、濃度には質量源・輸送、体感には日射・湿度が必要です。本気温差とは別に計算します。']];
let language='en', data=null, tab=0, opener=null;
const el=id=>document.getElementById(id);
const node=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
function cards(rows){const box=node('div',undefined,'guide-cards');for(const [title,body] of rows){const a=node('article');a.append(node('h3',title),node('p',body));box.append(a);}return box;}
function areaTable(c){const table=node('table',undefined,'guide-table');const head=node('tr');for(const t of ['',c.objects,c.size])head.append(node('th',t));table.append(head);for(const [key,name] of [['current',c.current],['revised',c.revised],['far_highrise',c.farHighrise],['expanded',c.expanded]]){const row=node('tr'),d=data[key];row.append(node('th',name),node('td',d.building_objects.toLocaleString()),node('td',d.size_m.map(v=>(v/1000).toFixed(2)).join(' × ')));table.append(row);}return table;}
function trialTable(c){const table=node('table',undefined,'guide-table');const h=node('tr');for(const title of ['', 'km',c.proxy])h.append(node('th',title));table.append(h);data.comparison_plan.cases.forEach((d,i)=>{const row=node('tr');row.append(node('th',c.trialNames[i]),node('td',d.size_m.map(v=>(v/1000).toFixed(3)).join(' × ')),node('td',(d.projected_blockage_proxy*100).toFixed(2)+'%'));table.append(row);});return table;}
function regionPanel(c){const box=node('div');box.append(node('p',c.regionTitle,'region-chain'),cards(c.regions),node('p',c.basis,'domain-basis'));if(data){box.append(node('h3',c.auditTitle),areaTable(c),node('h3',c.alignedTitle),trialTable(c),node('p',c.comparison),node('p',data.run_status?.localized?.[language]||c.notRun,'guide-status'));if(data.run_status?.record?.checked_utc){box.append(node('small',c.runSnapshot+' · '+new Date(data.run_status.record.checked_utc).toLocaleString({zh:'zh-CN',en:'en-GB',ja:'ja-JP'}[language],{timeZone:'Asia/Tokyo'})+' JST','run-snapshot'));}const a=node('a',c.raw);a.href='data/domain-audit.json';a.target='_blank';a.rel='noopener';box.append(a);}return box;}
function calculate(){if(!data)return;const a=+el('guideAlbedo').value,f=+el('guideFraction').value;el('guideAlbedoValue').textContent=a.toFixed(2);el('guideFractionValue').textContent=f.toFixed(2);el('guideQBefore').textContent=((1-.2)*data.GHI*f).toFixed(2)+' W/m²';el('guideQAfter').textContent=((1-a)*data.GHI*f).toFixed(2)+' W/m²';}
function calculator(c){const box=node('section',undefined,'guide-calculator');box.append(node('h3',c.calcTitle),node('p',c.calcNote));for(const [id,title,min,max,value] of [['guideAlbedo',c.albedo,.05,.85,.60],['guideFraction',c.fraction,.05,.4,.20]]){const label=node('label',title);label.htmlFor=id;const out=node('output',value.toFixed(2));out.id=id+'Value';label.append(out);const input=node('input');Object.assign(input,{id,type:'range',min,max,step:.01,value});input.addEventListener('input',calculate);box.append(label,input);}const result=node('div',undefined,'guide-calc-results');for(const [id,title] of [['guideQBefore',c.baseline],['guideQAfter',c.retrofit]]){const p=node('div');p.append(node('span',title));const output=node('strong');output.id=id;p.append(output);result.append(p);}box.append(result);return box;}
function render(){const c=terms[language];document.querySelectorAll('[data-guide-t]').forEach(n=>n.textContent=c[n.dataset.guideT]);if(!data)return;
 const nav=el('guideTabs');nav.replaceChildren();c.tabs.forEach((name,i)=>{const b=node('button',name);b.type='button';b.role='tab';b.id='guideTab'+i;b.setAttribute('aria-controls','guideContent');b.setAttribute('aria-selected',String(tab===i));b.tabIndex=tab===i?0:-1;b.className=tab===i?'active':'';b.addEventListener('click',()=>{tab=i;render();el('guideTab'+i).focus();});b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();tab=(i+(e.key==='ArrowRight'?1:-1)+c.tabs.length)%c.tabs.length;render();el('guideTab'+tab).focus();}});nav.append(b);});
 const body=el('guideContent');body.replaceChildren();body.setAttribute('aria-labelledby','guideTab'+tab);
 if(tab===0)body.append(node('p',c.intro,'guide-intro'),workflowLesson(language),readingSteps(language),cards(c.workflow));
 if(tab===1){body.append(node('p',c.formulaIntro,'guide-intro'),notation(language));const toggle=node('button',c.allFormulas,'equation-toggle');toggle.type='button';toggle.addEventListener('click',()=>{const list=[...body.querySelectorAll('details')],open=list.some(d=>!d.open);list.forEach(d=>d.open=open);toggle.textContent=open?c.collapseFormulas:c.allFormulas;});body.append(toggle);for(let i=0;i<c.formulaNames.length;i++){const d=node('details',undefined,'guide-equation');d.open=i===0;d.append(node('summary',c.formulaNames[i]),formulaLesson(i,language));body.append(d);}body.append(calculator(c));calculate();}
 if(tab===2){const table=node('table',undefined,'guide-table');const h=node('tr');for(const title of c.paramColumns)h.append(node('th',title));table.append(h);data.parameters.forEach(([a,b],i)=>{const row=node('tr');row.append(node('th',a),node('td',b),node('td',c.paramNotes[i]));table.append(row);});body.append(table);}
 if(tab===3)body.append(regionPanel(c));
 if(tab===4)body.append(readingSteps(language),indicatorsLesson(language),node('p',c.limits,'guide-status'));
 if(tab===5)body.append(numericalReviewPanel(language),node('p',c.limits,'guide-status'),cards(c.checks),node('p',c.criteria));
 const sources=el('guideSources'),details=node('details'),summary=node('summary',c.sources),links=node('div',undefined,'guide-source-links');for(const [name,href] of data.sources){const a=node('a',name);a.href=href;a.target='_blank';a.rel='noopener';links.append(a);}details.append(summary,links);sources.replaceChildren(details);
 const visible=el('domainRelationships');visible.replaceChildren(regionPanel(c));
 const audit=el('domainAuditSummary');audit.textContent=data.summary[language];
}
export function localizeCFDGuide(lang){language=terms[lang]?lang:'en';render();}
export async function initCFDGuide(lang){language=terms[lang]?lang:'en';const r=await fetch('data/domain-audit.json');if(!r.ok)throw Error('Domain audit:'+r.status);data=await r.json();await loadNumericalChecks();for(const [key,text] of [['zh','查看收敛与热收支 ↗'],['en','Convergence and heat checks ↗'],['ja','収束と熱収支を確認 ↗']])terms[key].checkRecords=text;render();for(const button of document.querySelectorAll('[data-open-guide]'))button.addEventListener('click',()=>{opener=button;tab=button.dataset.openGuide==='regions'?3:button.dataset.openGuide==='metrics'?4:button.dataset.openGuide==='checks'?5:0;render();el('cfdGuide').showModal();});el('closeCfdGuide').addEventListener('click',()=>el('cfdGuide').close());el('cfdGuide').addEventListener('close',()=>opener?.focus());document.body.dataset.guideReady='true';}
